using System;using System.IO;using System.Linq;using System.Xml;using System.Globalization;using System.Collections.Generic;using System.Windows.Forms;
namespace BeamScheduleFormatter {
static class CalculationStore {
 public static string StorageDirectory=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"BeamTools");public static event Action Changed;
 static string Key(LengthConfiguration c){return c.Input.Fc.ToString("R",CultureInfo.InvariantCulture)+"/"+c.GradeSmall+"/"+c.FySmall.ToString("R",CultureInfo.InvariantCulture)+"/"+c.GradeLarge+"/"+c.FyLarge.ToString("R",CultureInfo.InvariantCulture);}
 public static LengthConfiguration Clone(LengthConfiguration c){var d=new XmlDocument();var e=d.CreateElement("Configuration");c.Write(e);return LengthConfiguration.Read(e);}
 public static List<LengthConfiguration> All(){var list=new List<LengthConfiguration>();foreach(int fc in new[]{21,28,35})foreach(int small in new[]{40,60})foreach(int large in new[]{40,60})list.Add(new LengthConfiguration{Name="Built-in FC"+fc+" G"+small+"/G"+large,GradeSmall=small,GradeLarge=large,FySmall=small==40?275:420,FyLarge=large==40?275:420,Input=new LengthInput{Fc=fc,Round=25,Simplified=true}});list.Add(new LengthConfiguration{Name="Sample 27.6MPa / 414MPa",GradeSmall=60,GradeLarge=60,FySmall=414,FyLarge=414,Input=new LengthInput{Fc=27.6,Round=25,Simplified=true}});list.AddRange(Saved());return list;}
 static List<LengthConfiguration> Saved(){string path=Path.Combine(StorageDirectory,"SpliceDevelopmentHookConfigurations.xml");var list=new List<LengthConfiguration>();if(!File.Exists(path))return list;var d=new XmlDocument{XmlResolver=null};using(var r=XmlReader.Create(path,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=4000000}))d.Load(r);if(d.DocumentElement.Name!="CalculationConfigurations")throw new Exception("Invalid saved calculation configurations. Restore the local configuration store from a backup.");foreach(XmlElement e in d.DocumentElement.SelectNodes("Configuration"))list.Add(LengthConfiguration.Read(e));return list;}
 public static LengthConfiguration Resolve(double fc,int gs,double fs,int gl,double fl){var request=new LengthConfiguration{GradeSmall=gs,FySmall=fs,GradeLarge=gl,FyLarge=fl,Input=new LengthInput{Fc=fc}};var found=All().LastOrDefault(c=>Key(c)==Key(request));if(found!=null)return Clone(found);return new LengthConfiguration{Name="Built-in FC"+fc+" fy"+fs+"/"+fl,GradeSmall=gs,FySmall=fs,GradeLarge=gl,FyLarge=fl,Input=new LengthInput{Fc=fc,Round=25,Simplified=true}};}
 public static void Save(LengthConfiguration c){c.Validate();var list=Saved();list.RemoveAll(x=>x.Name.Equals(c.Name,StringComparison.OrdinalIgnoreCase));list.Add(Clone(c));var d=new XmlDocument();var root=d.CreateElement("CalculationConfigurations");d.AppendChild(root);foreach(var item in list){var e=d.CreateElement("Configuration");item.Write(e);root.AppendChild(e);}Directory.CreateDirectory(StorageDirectory);string path=Path.Combine(StorageDirectory,"SpliceDevelopmentHookConfigurations.xml"),temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{d.Save(temp);if(File.Exists(path))File.Replace(temp,path,path+".bak");else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}if(Changed!=null)Changed();}
 public static LengthConfiguration Choose(IWin32Window owner){var list=All();using(var f=new Form{Text="Saved splice, development & hook configurations",Width=700,Height=480,StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false}){var box=new ListBox{Dock=DockStyle.Fill,Font=new System.Drawing.Font("Segoe UI",10),HorizontalScrollbar=true};foreach(var c in list)box.Items.Add(c.Name+"  |  fc "+c.Input.Fc+"  |  fy "+c.FySmall+" / "+c.FyLarge);box.SelectedIndex=0;var ok=new Button{Text="Open selected",Dock=DockStyle.Bottom,Height=40,DialogResult=DialogResult.OK};f.Controls.Add(box);f.Controls.Add(ok);f.AcceptButton=ok;box.DoubleClick+=(s,e)=>{f.DialogResult=DialogResult.OK;f.Close();};return f.ShowDialog(owner)==DialogResult.OK?Clone(list[box.SelectedIndex]):null;}}
}
class SteelSelection {public int Grade;public double Fy;public override string ToString(){return "Grade "+Grade+" ("+Fy+" MPa)";}}
}
